Consider organizing code into functions for better maintainability:
```javascript
// Initialize app
function initTodoApp() {
  const elements = getDOMElements();
  validateElements(elements);
  setupEventListeners(elements);
}

function getDOMElements() {
  return {
    addButton: document.getElementById('add-btn'),
    todoInput: document.getElementById('todo-input'),
    todoList: document.getElementById('todo-list')
  };
}

function createTodoItem(text) {
  const todoItem = document.createElement('li');
  todoItem.className = 'todo-item';
  const span = document.createElement('span');
  span.textContent = text;
  const deleteBtn = document.createElement('button');
  deleteBtn.className = 'delete-btn';
  deleteBtn.textContent = 'Delete';
  todoItem.appendChild(span);
  todoItem.appendChild(deleteBtn);
  return todoItem;
}

function setupEventListeners({ addButton, todoInput, todoList }) {
  // Event delegation for delete
  todoList.addEventListener('click', (e) => {
    if (e.target.classList.contains('delete-btn')) {
      e.target.closest('.todo-item').remove();
    }
  });

  // Add button
  addButton.addEventListener('click', () => addTodo(todoInput, todoList));

  // Enter key
  todoInput.addEventListener('keypress', (e) => {
    if (e.key === 'Enter') addTodo(todoInput, todoList);
  });
}

function addTodo(input, list) {
  const text = input.value.trim();
  if (!text) return;

  const todoItem = createTodoItem(text);
  list.appendChild(todoItem);
  input.value = '';
}

// Initialize when DOM is ready
document.addEventListener('DOMContentLoaded', initTodoApp);
```

